def metric(data: pd.DataFrame) -> float:
    import numpy as np

    eqw_choices = 0
    total = 0

    for _, row in data.iterrows():
        a = tuple(row['option_a_ratings'])
        resp = row['response']

        if a == (0, 0, 10, 10):
            eqw_choices += (resp == 0)
            total += 1
        elif a == (9, 9, 0, 0):
            eqw_choices += (resp == 1)
            total += 1
        elif a == (2, 2, 8, 8):
            eqw_choices += (resp == 0)
            total += 1
        elif a == (8, 8, 2, 2):
            eqw_choices += (resp == 1)
            total += 1

    if total == 0:
        return 0.5
    return float(eqw_choices / total)

